INSERT INTO public.fishing_spots (name, location_name, location_lat, location_lng, description, photos, is_public, is_verified) VALUES
('Jacksonville Beach Pier', 'Jacksonville Beach', 30.291, -81.388, 'Catch the sunrise over the Atlantic. A historic pier perfect for ocean breezes, photos, and long walks after casting a line.', ARRAY['https://drive.google.com/uc?export=view&id=1M_aiXvOqv7sEnTzh_6gkH7Eq1aJEyq3S', 'https://drive.google.com/uc?export=view&id=1a4Ksp_MsANtY_09oOYZ81K4M_CZIeeDK', 'https://drive.google.com/uc?export=view&id=15dXgAKN2Hjkh7_xNwlVQRhFhx60l54lS'], true, true),
('St. Augustine Beach Pier', 'St. Augustine', 29.858, -81.267, 'Romantic beachside vibes. Features a splash park, local shops, and a historic lighthouse nearby for a full day out.', ARRAY['https://drive.google.com/uc?export=view&id=1Vilgbwy1To4IDPlsWYSYXO6HD5g5vCvI', 'https://drive.google.com/uc?export=view&id=1as96BLyWffsK8nQiwAyyuYdEcYq4qMKN', 'https://drive.google.com/uc?export=view&id=1pUBwmnK9MJtbucJ5XMwbczi7jChE8maN'], true, true),
('Fort Clinch Pier', 'Amelia Island', 30.704, -81.456, 'Fish with a historic fort backdrop. Massive pier with cool sea breezes and shaded forest trails for a picnic date.', ARRAY['https://drive.google.com/uc?export=view&id=1EV8c9ebY3A3w8tvjorHOnR2LK2GZ6vTS', 'https://drive.google.com/uc?export=view&id=1Jlvw9Tusap5QjNJ6DSlr78IJ8M3cFx_A', 'https://drive.google.com/uc?export=view&id=1FfeuHRFljrUZzn0gXphYMH8FV2Uw4AeA'], true, true),
('George Crady Bridge', 'Fernandina Beach', 30.514, -81.444, 'Mile-long pedestrian bridge over the sound. Perfect for long sunset walks and catching big redfish in a quiet setting.', ARRAY['https://drive.google.com/uc?export=view&id=1eSzEDC6i0zj5J1gIJ6i9Y4wfkrfDgpVO', 'https://drive.google.com/uc?export=view&id=1LwgwEwLsQv1e8502zAiDeDjmHvXUIuDN', 'https://drive.google.com/uc?export=view&id=1lP5Gv4ZKE1loHUIv6_nI48aE8gQrix70'], true, true),
('Vilano Beach Pier', 'St. Augustine', 29.916, -81.291, 'Sunset central! A short walk from quaint waterfront cafes; watch the sun dip into the Matanzas River together.', ARRAY['https://drive.google.com/uc?export=view&id=1UtG1G3ayMnGbvuEmaDzqUAFmL8iF2-G-', 'https://drive.google.com/uc?export=view&id=1nJf5eDk1ACHuWOF0DOfZ5Kr0GtOULua1', 'https://drive.google.com/uc?export=view&id=1QHquNswcK3TYK0TWbKCDkJSc98IMxFF7'], true, true),
('Reddie Point Preserve', 'Jacksonville', 30.381, -81.564, 'Hidden gem with panoramic river views. Quiet and private—great for an intimate sunset hangout and bird watching.', ARRAY['https://drive.google.com/uc?export=view&id=11nivecLUV_JQgzMs8JkJscQAnhiouWp_', 'https://drive.google.com/uc?export=view&id=1cmxpHUeWA7xBQMOl4SI9ZD-7rw-RXmrU', 'https://drive.google.com/uc?export=view&id=18QMs6vSSRy3ea3qi8KAOUqkGBaeDZBuW'], true, true),
('Memorial Park', 'Jacksonville', 30.311, -81.678, 'Historic park in the Riverside district. Cast a line then walk to nearby trendy craft beer bars and artisan coffee shops.', ARRAY['https://drive.google.com/uc?export=view&id=13yESCx2Msb_VNTvz3b2m1DUyonpJuSUi', 'https://drive.google.com/uc?export=view&id=16n5CrLl5zrZSmiBjey8nLjOUTTdUsdMB', 'https://drive.google.com/uc?export=view&id=1grjhk74VniyngABufh-GITCzfxFbaRUx'], true, true),
('Alpine Groves Park', 'St. Johns', 29.982, -81.631, 'Old Florida at its finest. Fish off the pier surrounded by ancient mossy oaks and historic citrus grove buildings.', ARRAY['https://drive.google.com/uc?export=view&id=1nsZ0lhdgV5_OyxXU83Ybk0Gz4o5xyMHJ', 'https://drive.google.com/uc?export=view&id=1HF2KJK7vKeU1vEMbsu4d4qAia7VagZ1r', 'https://drive.google.com/uc?export=view&id=1mCfo8uCaWcrS4Aw9MkHDSNX2q4ffT626'], true, true),
('Stockton Park', 'Jacksonville', 30.274, -81.716, 'Wide open river views and manicured lawns. A favorite for locals to picnic, fish at dusk, and enjoy the skyline view.', ARRAY['https://drive.google.com/uc?export=view&id=1Z9stVFwB1dQNYm_odQ8SP3o9e9h3tAcu', 'https://drive.google.com/uc?export=view&id=1tzNf_J-L21CNUOuSW8USXerQVnHyDWr7', 'https://drive.google.com/uc?export=view&id=1FCh_9HLw4C6TpHDLx_mOcpClZAaNxk-I'], true, true),
('Mandarin Park', 'Jacksonville', 30.155, -81.657, 'Secluded and quiet. Features lovely docks on the St. Johns River and winding shaded nature trails for a peaceful stroll.', ARRAY['https://drive.google.com/uc?export=view&id=1NDxp5-WzInBhIwpFN8vEoLay15JdETI5', 'https://drive.google.com/uc?export=view&id=1QByaKVbvo9J7Hj9Wy6UvvxHNVsixvkFa', 'https://drive.google.com/uc?export=view&id=1HLbi60-6Btlz6Q_NIS6MvOEDe5rKq8eu'], true, true),
('Kathryn Hanna Park', 'Atlantic Beach', 30.371, -81.399, 'Ocean and lake fishing in one spot. Rent a kayak for a fun water date in the freshwater lake or fish the surf.', ARRAY['https://drive.google.com/uc?export=view&id=1Fj2g743nD5SBgNGGmUVFRTcbPNsxnTn7', 'https://drive.google.com/uc?export=view&id=1L9EIXwlcsrFze8H41K4ltU9P9084Q9JG', 'https://drive.google.com/uc?export=view&id=1xwekBBFBGZ4S1Fio1JB85Jx2mZiGDci5'], true, true),
('Mayport Boat Ramp', 'Mayport', 30.395, -81.428, 'Watch the giant ferry and shrimp boats pass by while you catch trout on the jetty rocks. Very active and social.', ARRAY['https://drive.google.com/uc?export=view&id=1B_PuYETNdTOr0z5sc3uhVziK1ACfKCUI', 'https://drive.google.com/uc?export=view&id=14G2srrJ_EGlOkXOPX3l5gCzMlQ_-Yccd', 'https://drive.google.com/uc?export=view&id=1Fo50MIH6Oxj4V-W8pDJzSeWpt9Tmrk9z'], true, true),
('Sisters Creek Pier', 'Jacksonville', 30.404, -81.455, 'Busy waterway with great boat-watching. Very social spot near the famous Jim King Park with plenty of dock space.', ARRAY['https://drive.google.com/uc?export=view&id=1AAowlGEfc_l5344q1qbHh2ZkMI6DCFCp', 'https://drive.google.com/uc?export=view&id=1eX4LyvuuR7kJg_MDOnazRqaLki79VICp', 'https://drive.google.com/uc?export=view&id=1sQuFDLq07zumywj1ZchLyA3xFBceDm5v'], true, true),
('Castaway Preserve', 'Jacksonville', 30.273, -81.442, 'Scenic boardwalks through the marsh. Extremely "Instagrammable" and great for a nature-loving couple''s outing.', ARRAY['https://drive.google.com/uc?export=view&id=1GmoLb2v9cGziJLYO27TWv77djXdYarh1', 'https://drive.google.com/uc?export=view&id=1HqubXmmCiybyYBOEBZSRRVYQn7RNLk6j', 'https://drive.google.com/uc?export=view&id=1xyMdQTpv-fEJbRQlLj-WL0L4C568-EM6'], true, true),
('Bulls Bay Preserve', 'Jacksonville', 30.339, -81.821, 'Rugged and natural. A peaceful escape for couples who enjoy hiking through the woods to reach their fishing spot.', ARRAY['https://drive.google.com/uc?export=view&id=1IygUJPuMIgTRmW_P2wASBYbAcDAwZ_Gr', 'https://drive.google.com/uc?export=view&id=1TxVIimpIQGwMKtHvX2GMcCNsfueJl0oD', 'https://drive.google.com/uc?export=view&id=1uZaV72NIFMxgrBcdk0TLZu3VRqk3bOgu'], true, true),
('Trout River Pier', 'Jacksonville', 30.392, -81.652, 'Famous for night fishing. The overhead lights attract bait and create a cool, urban industrial atmosphere.', ARRAY['https://drive.google.com/uc?export=view&id=1dBv7cfmzw7ZnUHwNJof1AyEd4d0WeHHn', 'https://drive.google.com/uc?export=view&id=1dhYpDP0nVxIagBpDuHuGQvKdsxqPt0iF', 'https://drive.google.com/uc?export=view&id=10bdA-ArfmOLcGWyQGNDhQU7HhLiokver'], true, true),
('Blue Cypress Park', 'Jacksonville', 30.368, -81.604, 'Tucked away on the river. High-rated pier with a quiet, neighborhood feel for a low-key, stress-free day.', ARRAY['https://drive.google.com/uc?export=view&id=1PXKJLoUQH1TBBoi1QL1PYNV0Kb2t1ZiQ', 'https://drive.google.com/uc?export=view&id=1CKbiR8sc1tpI81PfqeayvpFr4K7yLNi1', 'https://drive.google.com/uc?export=view&id=1uEfCq6a74sPZ2NFSAmgGWUQMfPpLTU-A'], true, true),
('Dames Point Park', 'Jacksonville', 30.389, -81.558, 'Epic views of the massive cable-stayed bridge. Great for industrial-chic photography and watching giant ships.', ARRAY['https://drive.google.com/uc?export=view&id=1T-9O4RbzjsT837G4NujCiGsEtHnIa2Il', 'https://drive.google.com/uc?export=view&id=1Fb90xDhbg41oSPp0XZxQHr00SMAV2Cji', 'https://drive.google.com/uc?export=view&id=1dfey8rWAy-99fpICF5TvW6uVjKYbUEJW'], true, true),
('Favoretta Park', 'St. Augustine', 29.825, -81.256, 'Small and intimate. A quiet corner of the city perfect for a quick, private fishing date away from the tourists.', ARRAY['https://drive.google.com/uc?export=view&id=1h0E5qAkscVFbixbEWyWuvwXeG1bXTr5W', 'https://drive.google.com/uc?export=view&id=1azJ142LzlR6Fe7lhnG9fVMhmwdtJoNdw', 'https://drive.google.com/uc?export=view&id=1swon0nxi5gIfSmWCScTxQRgDI6zmuLc6'], true, true),
('Mickler''s Beach', 'Ponte Vedra', 30.148, -81.341, 'Known for shark tooth hunting. Surf fish in the morning and find prehistoric treasures in the sand together.', ARRAY['https://drive.google.com/uc?export=view&id=18r21Zx8NPvbp9qlU4Hyr2LJWYe-aaobA', 'https://drive.google.com/uc?export=view&id=1T_vv31ooDoqJGijDiYmtCFtV6O2sfmnc', 'https://drive.google.com/uc?export=view&id=13ySU7VKscADFNaKZgOUAKMr7XzwYLmZ3'], true, true);